#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    long long A, B;
    scanf("%d %lld %lld", &n, &A, &B);

    int *p = malloc((n+1) * sizeof(int));
    int *visited = calloc((n+1), sizeof(int));

    for (int i = 1; i <= n; i++) {
        scanf("%d", &p[i]);
    }

    long long total = 0;
    long long minAB = A < B ? A : B;

    for (int i = 1; i <= n; i++) {
        if (!visited[i] && p[i] != i) {
            // find cycle length
            int len = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = 1;
                j = p[j];
                len++;
            }
            // cost for this cycle
            long long cost = (long long)(len-1) * minAB;
            if (A + B < cost) cost = A + B;
            total += cost;
        } else {
            visited[i] = 1;
        }
    }

    printf("%lld\n", total);

    free(p);
    free(visited);
    return 0;
}

#include <stdio.h>

int main() {
    int N;
    long long A, B;
    scanf("%d %lld %lld", &N, &A, &B);
    int p[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &p[i]);
    }

    // longest prefix already sorted
    int prefix = 0;
    while (prefix < N && p[prefix] == prefix + 1) {
        prefix++;
    }

    // longest suffix already sorted
    int suffix = 0;
    while (suffix < N && p[N - 1 - suffix] == N - suffix) {
        suffix++;
    }

    // Minimum shifts needed
    long long left_shifts = N - prefix;
    long long right_shifts = N - suffix;

    long long cost_left = left_shifts * A;
    long long cost_right = right_shifts * B;

    long long ans = cost_left < cost_right ? cost_left : cost_right;

    // Also consider mixing: use cheaper operation for all shifts needed
    long long min_cost_per_shift = A < B ? A : B;
    long long min_shifts = left_shifts < right_shifts ? left_shifts : right_shifts;
    long long mixed_cost = min_shifts * min_cost_per_shift + (N - min_shifts) * (A > B ? A : B);

    if (mixed_cost < ans) ans = mixed_cost;

    printf("%lld\n", ans);
    return 0;
}

