typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    ll A, B;
    if (scanf("%d %lld %lld", &N, &A, &B) != 3) return 0;

    int *p = (int *)malloc((N + 1) * sizeof(int));
    int *pos = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) {
        scanf("%d", &p[i]);
        pos[p[i]] = i;
    }

    /*
      Let d[i] = pos[i] - i.
      If we choose a cut k (cyclic interpretation), elements with d[i] <= k
      are fixed using right shifts, others using left shifts.
      Cost(k) = B * count(d<=k) + A * count(d>k).

      Valid k values are between min(d) and max(d)-1, and also the two extremes
      correspond to all-left / all-right.
      Since cost only changes when crossing some d[i], it is enough to evaluate:
      - all-left: A*N
      - all-right: B*N
      - for each distinct d value x: after moving k past x, all elements with d<=x
        switch from left to right, changing total by (B-A) each.
    */

    ll *d = (ll *)malloc(N * sizeof(ll));
    for (int i = 1; i <= N; i++) d[i - 1] = (ll)pos[i] - i;

    qsort(d, N, sizeof(ll), cmp_ll);

    ll ans = A * (ll)N;   // all use left shifts
    ll cur = ans;

    int i = 0;
    while (i < N) {
        int j = i;
        while (j < N && d[j] == d[i]) j++;
        int cnt = j - i;
        cur += (B - A) * (ll)cnt;
        if (cur < ans) ans = cur;
        i = j;
    }

    // all use right shifts
    ll all_right = B * (ll)N;
    if (all_right < ans) ans = all_right;

    printf("%lld\n", ans);

    free(p);
    free(pos);
    free(d);
    return 0;
}

