int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long A, B;
    cin >> N >> A >> B;

    vector<int> p(N);
    for (int i = 0; i < N; i++) cin >> p[i];

    // Find longest prefix where p[i] == i+1
    int sorted_prefix = 0;
    while (sorted_prefix < N && p[sorted_prefix] == sorted_prefix + 1) {
        sorted_prefix++;
    }

    if (sorted_prefix == N) {
        cout << 0 << "\n";
        return 0;
    }

    // Find longest suffix where p[i] == i+1
    int sorted_suffix = N - 1;
    while (sorted_suffix >= 0 && p[sorted_suffix] == sorted_suffix + 1) {
        sorted_suffix--;
    }

    int unsorted_len = sorted_suffix - sorted_prefix + 1;

    // We can either:
    // 1. Rotate the unsorted middle to correct positions using left/right shifts
    // 2. Or break it differently

    long long cost_left_only = A * (unsorted_len - 1);
    long long cost_right_only = B * (unsorted_len - 1);

    // Try mixtures: We can shift left some times and right some times
    // Minimum cost is basically min of left-only, right-only, or mix
    // But mix is rarely better than the cheaper of the two directions
    long long ans = min(cost_left_only, cost_right_only);

    // Also consider: maybe cheaper to shift the whole array partially
    // The minimal cost is min(A, B) * (unsorted_len - 1)
    ans = min(ans, min(A, B) * (unsorted_len - 1));

    cout << ans << "\n";

    return 0;
}

