    for (int i = 1; i <= N; ++i) {
        if (vis[i]) continue;

        int cur = i;
        int len = 0;
        while (!vis[cur]) {
            vis[cur] = 1;
            cur = pos[cur];
            ++len;
        }

        if (len > 1) {
            ans += 1LL * (len - 1) * min(A, B);
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class SortWithShifts {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int A = sc.nextInt();
        int B = sc.nextInt();
        int[] p = new int[N];
        for (int i = 0; i < N; i++) {
            p[i] = sc.nextInt();
        }

        boolean sorted = true;
        for (int i = 0; i < N; i++) {
            if (p[i] != i + 1) {
                sorted = false;
                break;
            }
        }

        if (sorted) {
            System.out.println(0);
        } else {
            System.out.println(Math.min(A, B));
        }

        sc.close();
    }
}

